using System;
using System.IO;
using MassiveArmy.Industrial;
static class InventorySlotChecks {
 static InventoryAddress P(int slot)=>new InventoryAddress{slot=slot};
 static ItemStack Find(Inventory inventory,string item){foreach(var stack in inventory.items)if(stack.item==item)return stack;return null;}
 public static void Run(Action<bool,string> check){
  var world=new IndustrialWorld{creativeMode=true};var actor=world.Register(1,new FramePose{body=1,y=10000});actor.inventory.capacity=10000;actor.inventory.items.Clear();using(var a=new IndustrialAuthority(world)){
   a.EnableInventories();check(actor.inventory.slotLimit==40&&world.inventoryWorkflow,"Player inventory enables a single finite backpack and ten physical hotbar slots");
   a.ChangePersonalItem(1,"iron-bar",1500,true);check(actor.inventory.items.Count==2&&actor.inventory.Count("iron-bar")==1500,"Resources form real bounded stacks without changing total quantity");var iron=Find(actor.inventory,"iron-bar");int original=iron.slot;check(a.MoveInventory(1,P(original),P(0),1000)==null&&actor.inventory.AtSlot(0).count==1000,"Dragging a stack into the hotbar moves it out of the backpack");
   var spare=Find(actor.inventory,"iron-bar");if(spare.slot==0)foreach(var stack in actor.inventory.items)if(stack.slot!=0){spare=stack;break;}check(a.MoveInventory(1,P(0),P(spare.slot),100)==null&&actor.inventory.AtSlot(0).count==900&&actor.inventory.AtSlot(spare.slot).count==600,"Partial stack merges conserve both stacks");
   a.ChangePersonalItem(1,"copper-bar",20,true);int copper=Find(actor.inventory,"copper-bar").slot;check(a.MoveInventory(1,P(0),P(copper),900)==null&&actor.inventory.AtSlot(0).item=="copper-bar"&&actor.inventory.AtSlot(copper).item=="iron-bar","Complete unlike stacks swap atomically");check(a.MoveInventory(1,P(0),P(1),1,"stone")!=null&&actor.inventory.AtSlot(0).count==20,"A stale drag cannot move an item that replaced its source");
   a.SelectInventorySlot(1,0);a.ChangePersonalItem(1,"copper-bar",20,false);check(actor.inventory.AtSlot(0)==null&&actor.inventory.Count("copper-bar")==0,"Consuming the equipped stack clears that exact hotbar slot");
   a.ChangePersonalItem(1,IndustrialCatalog.MachineItem("solar-panel"),2,true);var solar=Find(actor.inventory,IndustrialCatalog.MachineItem("solar-panel"));a.MoveInventory(1,P(solar.slot),P(0),1);a.SelectInventorySlot(1,0);var placement=new IndustrialCommand{sequence=actor.lastSequence+1,kind="place",definition="solar-panel",pose=new FramePose{body=1,x=8,y=10000}};check(a.Execute(1,placement).accepted&&actor.inventory.AtSlot(0)==null&&actor.inventory.Count(IndustrialCatalog.MachineItem("solar-panel"))==1,"A placed nonstackable machine consumes its equipped item, including in Creative, without selecting another copy");
   var store=new IndustrialMachine{id=world.AllocateId(),owner=1,definition="store",pose=new FramePose{body=1,x=4,y=10000},input=new Inventory{capacity=2000,slotLimit=-1}};world.machines.Add(store);var source=Find(actor.inventory,"iron-bar");var machineSlot=new InventoryAddress{entity=store.id,section="input",slot=0};check(a.MoveInventory(1,P(source.slot),machineSlot,100)==null&&store.input.AtSlot(0).count==100,"Vehicle and machine storage accept dragged stacks through the shared authority");check(a.MoveInventory(1,P(copper),new InventoryAddress{entity=store.id,section="output",slot=0},1)!=null,"Players cannot inject items into a machine output slot");
   actor.inventory.bulk=new MaterialLot{litres=200,iron=40,copper=20,activity=70};check(a.MoveInventory(1,P(-2),new InventoryAddress{entity=store.id,section="input",slot=-2},100)==null&&store.input.bulk.litres==100&&store.input.bulk.iron==20&&store.input.bulk.activity==35,"Bulk slots transfer pay dirt with exact grade and radioactive activity");
   var tank=new IndustrialMachine{id=world.AllocateId(),owner=1,definition="water-reservoir",pose=new FramePose{body=1,x=5,y=10000}};world.machines.Add(tank);a.ChangePersonalItem(1,"water",20,true);var water=Find(actor.inventory,"water");check(a.MoveInventory(1,P(water.slot),new InventoryAddress{entity=tank.id,section="reservoir"},10)==null&&tank.water==10&&actor.inventory.Count("water")==10,"Dragging water into the reservoir slot fills its fluid quantity");
   var other=world.Register(2,new FramePose{body=1,y=10000});check(a.MoveInventory(2,machineSlot,P(0),1)!=null,"Container drags enforce ownership and reach");actor.pose.x=100;check(a.MoveInventory(1,machineSlot,P(0),1)!=null,"Moving away invalidates a container transfer");actor.pose.x=0;
  }
  var reservedWorld=new IndustrialWorld();var reserved=reservedWorld.Register(1,new FramePose{body=1,y=10000});reserved.inventory.items.Clear();using(var a=new IndustrialAuthority(reservedWorld)){a.EnableInventories();reserved.inventory.Add("stone",4);for(int i=0;i<39;i++){IndustrialCatalog.RegisterPersonalItem("filler#"+i);reserved.inventory.Add("filler#"+i,1);}check(reserved.inventory.items.Count==40,"Backpack capacity counts stacks rather than item type aliases");var command=new IndustrialCommand{sequence=1,kind="craft",item=IndustrialCatalog.MachineItem("workbench"),count=1};check(a.Execute(1,command).accepted&&!reserved.inventory.CanAdd("fuel",1),"Crafting reserves the output slot released by its consumed ingredients");a.Step(40);check(reserved.inventory.Count(IndustrialCatalog.MachineItem("workbench"))==1&&reserved.inventory.items.Count==40,"A reserved craft completes into a full inventory without losing its output");}
  string path=Path.GetFullPath("TestResults/Industrial/InventorySlots/recovery-"+Guid.NewGuid().ToString("N")+".xml");Directory.CreateDirectory(Path.GetDirectoryName(path));var saved=new IndustrialWorld();var owner=saved.Register(1,new FramePose{body=1,y=10000});owner.inventory.items.Clear();long dropId;
  using(var a=new IndustrialAuthority(saved,path)){a.EnableInventories();owner.inventory.Add("isotope",2,99);a.Save();var isotope=Find(owner.inventory,"isotope");check(a.DropInventory(1,P(isotope.slot),1,new FramePose{body=1,x=2,y=10000},new FramePose{body=1,x=2,y=10000},"isotope")==null,"Dropping creates a persisted recoverable ground stack");dropId=saved.droppedItems[0].id;check(saved.droppedItems[0].inventory.ActivityOf("isotope",1)==49.5&&owner.inventory.ActivityOf("isotope",1)==49.5,"Dropping preserves radioactive quantity and activity exactly");a.Step();check(owner.exposure>49.5,"Dropped radioactive material remains a nearby emitter");}
  var replay=IndustrialAuthority.Load(path);check(replay.droppedItems.Count==1&&replay.droppedItems[0].id==dropId&&replay.Actor(1).inventory.Count("isotope")==1,"Journal recovery restores the ground pile without duplicating carried items");using(var a=new IndustrialAuthority(replay)){check(a.MoveInventory(1,new InventoryAddress{entity=dropId,section="ground",slot=0},P(0),1)==null&&replay.droppedItems.Count==0&&replay.Actor(1).inventory.Count("isotope")==2,"Picking up the final ground stack removes its empty pile");}
  var migrated=new Inventory{capacity=5000};for(int i=0;i<45;i++){IndustrialCatalog.RegisterPersonalItem("legacy#"+i);migrated.Add("legacy#"+i,1);}migrated.EnableSlots(40);check(migrated.Used==45&&migrated.items.Count==45&&!migrated.CanAdd("stone",1),"Oversized old inventories retain visible overflow instead of deleting items");
  check(IndustrialCatalog.Recipes.ContainsKey(IndustrialCatalog.ModuleItem("WarehouseRoom"))&&IndustrialCatalog.Handcraft.Contains(IndustrialCatalog.MachineItem("truck")),"Buildings and vehicles are crafted as equipable items using their resource bills");
 }
}
